/**
 * Signals in message EkfLean.
 *
 * rt-core EKF lean (roll) angle estimate for the cornering decision (hardware-architecture 5b.2 Layer 2). Until the EKF has converged after a restart, rt-core sends LEAN_ANGLE_STATE=INVALID and QUALITY=0.
 *
 * All signal values are as on the CAN bus.
 */
struct platform_ekf_lean_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_counter;

    /**
     * Estimate state: ESTIMATED, CLAMPED to the physical range, or INVALID. There is no safe default lean angle: rt-core sends INVALID instead (D-029); 2 is reserved and must be treated as INVALID.
     *
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t lean_angle_state;

    /**
     * Roll angle; positive = leaning right.
     *
     * Range: -9000..9000 (-90..90 deg)
     * Scale: 0.01
     * Offset: 0
     */
    int16_t lean_angle;

    /**
     * Estimator confidence; 0 = no confidence.
     *
     * Range: 0..100 (0..100 %)
     * Scale: 1
     * Offset: 0
     */
    uint8_t lean_angle_quality;
};

/**
 * Signals in message VehicleSpeed.
 *
 * Vehicle speed republished by rt-core from CL250 DID 0xF40D (D-021). Not a safety-node input (D-041): the Layer 1 cornering decision needs no speed. It keeps its safety-range ID and E2E protection for its other consumers; no safety decision may be based on it.
 *
 * All signal values are as on the CAN bus.
 */
struct platform_vehicle_speed_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_counter;

    /**
     * 1 = VEHICLE_SPEED holds an ECU sample younger than stale_after_ms of DID 0xF40D (uds/vehicle_cl250.yaml); 0 = no valid source value. E2E OK only proves the rt-core link is fresh; consumers that care about freshness also bound VEHICLE_SPEED_AGE.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t vehicle_speed_valid;

    /**
     * Range 0-255 km/h = the range of DID 0xF40D (one byte, formula A). The source resolution is 1 km/h; the 0.01 scale does not add precision today and leaves room for a finer fused speed later (Q-015).
     *
     * Range: 0..25500 (0..255 km/h)
     * Scale: 0.01
     * Offset: 0
     */
    uint16_t vehicle_speed;

    /**
     * Age of the source sample when rt-core wrote this frame, counted from the send time of the oldest unanswered read of DID 0xF40D (D-051), so never younger than the ECU sample; nearest 10 ms, saturates at 2550 ms; an INVALID speed sends 2550 (D-056). It does not include the wait in the TX buffer (at most one write of rt-core): the worst case for a VALID frame at its consumer is stale_after_ms of DID 0xF40D + one cycle + one rt-core comms pass (about 351 ms).
     *
     * Range: 0..255 (0..2550 ms)
     * Scale: 10
     * Offset: 0
     */
    uint8_t vehicle_speed_age;
};

/**
 * Signals in message EkfFrictionMass.
 *
 * rt-core EKF road friction and total mass estimates for the cornering decision (hardware-architecture 5b.2 Layer 2). Until the EKF has converged after a restart, rt-core sends *_STATE=INVALID and QUALITY=0.
 *
 * All signal values are as on the CAN bus.
 */
struct platform_ekf_friction_mass_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_counter;

    /**
     * Estimate state: ESTIMATED, CLAMPED to the physical range, DEFAULT fallback value, or INVALID. Consumers must never treat DEFAULT as ESTIMATED; the DEFAULT values are in limits/platform_limits.yaml (D-029).
     *
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t friction_coeff_state;

    /**
     * Estimate state: ESTIMATED, CLAMPED to the physical range, DEFAULT fallback value, or INVALID. Consumers must never treat DEFAULT as ESTIMATED; the DEFAULT values are in limits/platform_limits.yaml (D-029).
     *
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t total_mass_state;

    /**
     * Estimated tyre-road friction coefficient mu (dimensionless).
     *
     * Range: 0..2000 (0..2 -)
     * Scale: 0.001
     * Offset: 0
     */
    uint16_t friction_coeff;

    /**
     * Range: 0..100 (0..100 %)
     * Scale: 1
     * Offset: 0
     */
    uint8_t friction_coeff_quality;

    /**
     * Estimated total mass (vehicle + rider + load).
     *
     * Range: 0..10000 (0..1000 kg)
     * Scale: 0.1
     * Offset: 0
     */
    uint16_t total_mass;

    /**
     * Range: 0..100 (0..100 %)
     * Scale: 1
     * Offset: 0
     */
    uint8_t total_mass_quality;
};

